package ar.com.miflix.admin

import com.google.gson.*
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

internal object LegacyFixtures {
    fun obj(s:String)=JsonParser.parseString(s).asJsonObject
    fun item(id:String="s",type:String="serie")=obj("""{"id":"$id","tipo":"$type","titulo":"Título propio $id","sinopsis":"Sinopsis manual original","fecha_agregado":"2024-01-01T00:00:00Z","poster_url":"https://image.tmdb.org/t/p/w500/a.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/b.jpg","telegram_url":"https://t.me/synthetic/1","telegram_message_id":1,"playback_id":"keep-playback","unknown":{"keep":true},"temporadas":[{"id":"season-id","numero":0,"nombre":"Especiales","episodios":[{"id":"special-id","numero":1,"titulo":"Especial propio","telegram_url":"https://t.me/synthetic/2"}]},{"id":"season-one-id","numero":1,"nombre":"Temporada 1","episodios":[{"id":"episode-id","numero":1,"titulo":"Nombre propio","sinopsis":"Sinopsis propia del capítulo","duracion":"42","imagen_url":"https://image.tmdb.org/t/p/w500/still.jpg","telegram_url":"https://t.me/synthetic/3","telegram_message_id":3,"playback_id":"episode-playback"}]}]}""")
    fun catalog(vararg values:JsonObject)=obj("""{"schema_version":1,"items":[],"unknown_root":{"preserve":true},"colecciones_version":1,"colecciones":[{"id":"remote-collection","titulos":["s","absent"],"future":7}]}""").apply {add("items",JsonArray().apply {values.forEach {add(it.deepCopy())}})}
    fun target(item:JsonObject,path:String):JsonObject {val p=path.split('/');if(p[0]=="title") return item;val s=item.array("temporadas").first {it.asJsonObject.text("numero")==p[0]}.asJsonObject;return if(p[1]=="season") s else s.array("episodios").first {it.asJsonObject.text("numero")==p[1]}.asJsonObject}
    fun marked(original:JsonObject,path:String="1/1/sinopsis",value:JsonElement=JsonPrimitive("Sinopsis sintética retirada del proveedor histórico")):JsonObject=original.deepCopy().apply {
        target(this,path).add(path.substringAfterLast('/'),value.deepCopy())
        val sources=get("fuentes_metadata")?.takeIf {it.isJsonObject}?.asJsonObject ?: JsonObject().also {add("fuentes_metadata",it)}
        val rec=sources.get("recuperacion_selectiva")?.takeIf {it.isJsonObject}?.asJsonObject ?: JsonObject().also {sources.add("recuperacion_selectiva",it)}
        rec.add(path,obj("""{"fuente":"TheTVDB","url":"https://thetvdb.com/series/synthetic","idioma":"spa","publicacion_bloqueada":true}"""))
    }
    class Store:StateStore {
        var data:JsonObject?=null;var failWrite=false;var failArchive=false;val archives=linkedMapOf<String,JsonObject>()
        override fun read()=data?.deepCopy()
        override fun write(state:JsonObject) {check(!failWrite) {"synthetic disk failure"};data=state.deepCopy()}
        override fun archive(state:JsonObject):String {check(!failArchive) {"synthetic archive failure"};val id=RetiredMetadata.hash(JsonPrimitive(state.toString()));archives.putIfAbsent(id,state.deepCopy());return id}
        override fun readArchive(id:String)=archives.getValue(id).toString()
    }
    class Remote(var root:JsonObject):AdminRemote {var writes=0;var fail=false;override fun download()=root.deepCopy();override fun publish(catalog:JsonObject){check(!fail) {"synthetic network failure"};writes++;root=catalog.deepCopy()}}
    fun state(current:JsonObject,base:JsonObject?=null)=JsonObject().apply {add("catalog",current.deepCopy());base?.let {add("base",it.deepCopy())};addProperty("pending",true)}
}
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[28],manifest=Config.NONE)
class RetiredMetadataTest {
    private fun item()=LegacyFixtures.item()
    private fun root(i:JsonObject=item())=LegacyFixtures.catalog(i)
    private fun first(r:JsonObject)=CatalogRules.items(r).first()
    private fun path(i:JsonObject,p:String)=LegacyFixtures.target(i,p).get(p.substringAfterLast('/'))
    private fun migrate(raw:JsonObject)=RetiredMetadata.migrate(raw).state
    @Test fun cleanCatalogIsExactlyUnchanged() {val s=LegacyFixtures.state(root(),root());assertEquals(s,migrate(s));assertEquals(root(),CatalogRules.publicCopy(root()))}
    @Test fun selectedEpisodeSynopsisRemovedWithoutLosingOtherData() {val bad=LegacyFixtures.marked(item());val projected=first(CatalogRules.publicCopy(root(bad)));val expected=item();LegacyFixtures.target(expected,"1/1/sinopsis").remove("sinopsis");expected.add("fuentes_metadata",LegacyFixtures.obj("""{"recuperacion_selectiva":{}}"""));assertEquals(expected,projected)}
    @Test fun mixedTmdbAndTvmazeProvenancePreserved() {val bad=LegacyFixtures.marked(item());val rec=bad.getAsJsonObject("fuentes_metadata").getAsJsonObject("recuperacion_selectiva");rec.add("title/season/poster_url",LegacyFixtures.obj("""{"fuente":"TMDB","url":"https://www.themoviedb.org/movie/1"}"""));rec.add("1/1/titulo",LegacyFixtures.obj("""{"fuente":"TVmaze","licencia":"https://creativecommons.org/licenses/by-sa/4.0/","atribucion":"TVmaze"}"""));val before=rec.deepCopy();val out=first(CatalogRules.publicCopy(root(bad)));val kept=out.getAsJsonObject("fuentes_metadata").getAsJsonObject("recuperacion_selectiva");assertEquals(before.get("title/season/poster_url"),kept.get("title/season/poster_url"));assertEquals(before.get("1/1/titulo"),kept.get("1/1/titulo"));assertEquals(bad.get("poster_url"),out.get("poster_url"))}
    @Test fun trustedBaseRestoresOriginalFieldAndItsProvenance() {val original=item();original.add("fuentes_metadata",LegacyFixtures.obj("""{"recuperacion_selectiva":{"1/1/sinopsis":{"fuente":"TVmaze","licencia":"CC BY-SA"}}}"""));val next=migrate(LegacyFixtures.state(root(LegacyFixtures.marked(original)),root(original)));val out=first(next.getAsJsonObject("catalog"));assertEquals(path(original,"1/1/sinopsis"),path(out,"1/1/sinopsis"));assertEquals(original.get("fuentes_metadata"),out.get("fuentes_metadata"))}
    @Test fun undoBeforeUsedOnlyWhenAfterMatchesAffectedFields() {val before=item();val after=LegacyFixtures.marked(before);val s=LegacyFixtures.state(root(after));s.add("metadata_undo",JsonObject().apply {add("before",before);add("after",after);add("paths",JsonArray())});val next=migrate(s);assertEquals(path(before,"1/1/sinopsis"),path(first(next.getAsJsonObject("catalog")),"1/1/sinopsis"));assertEquals(s.get("metadata_undo"),next.get("metadata_undo"))}
    @Test fun unrelatedUndoCannotRestoreField() {val bad=LegacyFixtures.marked(item());val s=LegacyFixtures.state(root(bad));s.add("metadata_undo",JsonObject().apply {add("before",LegacyFixtures.item("other"));add("after",bad)});assertNull(path(first(migrate(s).getAsJsonObject("catalog")),"1/1/sinopsis"))}
    @Test fun mismatchedUndoAfterDoesNotInventOriginal() {val bad=LegacyFixtures.marked(item());val s=LegacyFixtures.state(root(bad));s.add("metadata_undo",JsonObject().apply {add("before",item());add("after",LegacyFixtures.marked(item(),value=JsonPrimitive("Different historical version")))});assertNull(path(first(migrate(s).getAsJsonObject("catalog")),"1/1/sinopsis"))}
    @Test fun originalAlreadyRestrictedIsNotReusedAsFallback() {val old=LegacyFixtures.marked(item());val s=LegacyFixtures.state(root(old),root(old));assertNull(path(first(migrate(s).getAsJsonObject("catalog")),"1/1/sinopsis"))}
    @Test fun mainTitleWithNoSafeOriginalGetsExplicitReviewLabelNotDeletedRecord() {val bad=LegacyFixtures.marked(item(),"title/season/titulo",JsonPrimitive("Título retirado"));val out=CatalogRules.publicCopy(root(bad));CatalogRules.parse(out.toString());assertEquals(1,CatalogRules.items(out).size);assertTrue(first(out).text("titulo").contains("revisar título"));assertEquals("s",first(out).text("id"))}
    @Test fun mainTitleCanBeRestoredFromTrustedBase() {val s=LegacyFixtures.state(root(LegacyFixtures.marked(item(),"title/season/titulo",JsonPrimitive("Retirado"))),root());assertEquals(item().get("titulo"),first(migrate(s).getAsJsonObject("catalog")).get("titulo"))}
    @Test fun seasonDescriptionAndNameHandledWithoutDeletingSeasonOrEpisodes() {var bad=LegacyFixtures.marked(item(),"1/season/nombre",JsonPrimitive("Nombre retirado"));bad=LegacyFixtures.marked(bad,"1/season/sinopsis");val out=first(CatalogRules.publicCopy(root(bad)));assertEquals(2,out.array("temporadas").size());assertEquals(1,out.array("temporadas")[1].asJsonObject.array("episodios").size());assertFalse(out.array("temporadas")[1].asJsonObject.has("nombre"))}
    @Test fun seasonZeroKeptAndOnlyItsMarkedFieldRemoved() {val bad=LegacyFixtures.marked(item(),"0/1/titulo",JsonPrimitive("Especial retirado"));val out=first(CatalogRules.publicCopy(root(bad)));assertEquals(0L,out.array("temporadas")[0].asJsonObject.number("numero"));assertEquals("special-id",out.array("temporadas")[0].asJsonObject.array("episodios")[0].asJsonObject.text("id"))}
    @Test fun numericDurationRestrictionDoesNotRemoveEqualUnmarkedDurationElsewhere() {val bad=LegacyFixtures.marked(item(),"1/1/duracion",JsonPrimitive("42"));bad.addProperty("duracion","42");val out=first(CatalogRules.publicCopy(root(bad)));assertEquals("42",out.text("duracion"));assertNull(path(out,"1/1/duracion"))}
    @Test fun copiesAndAliasesOfIdentifiedRestrictedTextAlsoRemoved() {val bad=LegacyFixtures.marked(item());val text=path(bad,"1/1/sinopsis")!!.asString;bad.addProperty("sinopsis",text);bad.addProperty("custom_description","  $text   ");val out=first(CatalogRules.publicCopy(root(bad)));assertFalse(out.has("sinopsis"));assertFalse(out.has("custom_description"))}
    @Test fun unchangedManualFieldsWithoutRestrictedProvenancePreserved() {val bad=LegacyFixtures.marked(item());bad.addProperty("manual_custom","Mis comentarios manuales propios");val out=first(CatalogRules.publicCopy(root(bad)));assertEquals("Mis comentarios manuales propios",out.text("manual_custom"));assertEquals(item().get("unknown"),out.get("unknown"));assertEquals(item().get("poster_url"),out.get("poster_url"))}
    @Test fun identicalIndependentRemoteFieldIsNotMistakenForIllicitCopy() {val bad=LegacyFixtures.marked(item());val base=item().apply {add("sinopsis",path(bad,"1/1/sinopsis")!!.deepCopy())};bad.add("sinopsis",base.get("sinopsis"));val out=first(migrate(LegacyFixtures.state(root(bad),root(base))).getAsJsonObject("catalog"));assertEquals(base.get("sinopsis"),out.get("sinopsis"))}
    @Test fun protectedIdsTelegramAndDateRemainByteForByte() {val bad=LegacyFixtures.marked(item());val before=bad.deepCopy();val out=first(CatalogRules.publicCopy(root(bad)));for(f in listOf("id","tipo","fecha_agregado","telegram_url","telegram_message_id","playback_id")) assertEquals(before.get(f),out.get(f));val a=LegacyFixtures.target(before,"1/1/titulo");val b=LegacyFixtures.target(out,"1/1/titulo");for(f in listOf("id","numero","telegram_url","telegram_message_id","playback_id")) assertEquals(a.get(f),b.get(f))}
    @Test fun missingHistoricalDateIsNotInvented() {val bad=LegacyFixtures.marked(item().apply {remove("fecha_agregado")});assertFalse(first(CatalogRules.publicCopy(root(bad))).has("fecha_agregado"))}
    @Test fun restrictedImageDomainIsRemovedButTmdbAndManualArtworkRemain() {val i=item().apply {addProperty("logo_url","https://artworks.thetvdb.com/logo.jpg")};val out=first(CatalogRules.publicCopy(root(i)));assertFalse(out.has("logo_url"));assertEquals(i.get("poster_url"),out.get("poster_url"));assertEquals(i.get("backdrop_url"),out.get("backdrop_url"))}
    @Test fun unknownNestedExplicitRetiredObjectQuarantinedOnlyThere() {val i=item().apply {add("future_metadata",LegacyFixtures.obj("""{"provider":"TheTVDB","text":"Restricted content"}"""));addProperty("future_normal","keep")};val out=first(CatalogRules.publicCopy(root(i)));assertFalse(out.has("future_metadata"));assertEquals("keep",out.text("future_normal"));assertEquals(i.get("titulo"),out.get("titulo"))}
    @Test fun ambiguousUnmappedProvenanceGetsSpecificIssueWithoutDroppingRecord() {val i=item().apply {add("fuentes_metadata",LegacyFixtures.obj("""{"recuperacion_selectiva":{"99/3/sinopsis":{"fuente":"TheTVDB"}}}"""))};val s=migrate(LegacyFixtures.state(root(i)));assertTrue(s.getAsJsonObject(RetiredMetadata.STATE).array("issues").any {it.asJsonObject.text("path")=="99/3/sinopsis"});assertEquals(1,CatalogRules.items(s.getAsJsonObject("catalog")).size)}
    @Test fun unrelatedMetadataSourceNamesAreNotTreatedAsRetired() {val i=item().apply {addProperty("fuente","MANUAL");addProperty("fuente_principal","TMDB");add("fuentes_metadata",LegacyFixtures.obj("""{"sinopsis":"TVmaze","poster":"TMDB"}"""))};assertEquals(root(i),CatalogRules.publicCopy(root(i)))}
    @Test fun unknownRootAndRemoteCollectionsPreservedExactly() {val r=root(LegacyFixtures.marked(item()));val out=CatalogRules.publicCopy(r);assertEquals(r.get("unknown_root"),out.get("unknown_root"));assertEquals(r.get("colecciones"),out.get("colecciones"));assertEquals(r.get("colecciones_version"),out.get("colecciones_version"))}
    @Test fun cleaningDoesNotMutateInputSnapshot() {val s=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());val before=s.deepCopy();migrate(s);assertEquals(before,s)}
    @Test fun migrationIsIdempotent() {val first=migrate(LegacyFixtures.state(root(LegacyFixtures.marked(item())),root()));assertEquals(first,migrate(first))}
    @Test fun historicalUndoIsRetainedExactly() {val s=LegacyFixtures.state(root());s.add("metadata_undo",JsonObject().apply {add("before",item());add("after",LegacyFixtures.marked(item()));add("future_history",JsonArray())});val out=migrate(s);assertEquals(s.get("metadata_undo"),out.get("metadata_undo"));assertFalse(RetiredMetadata.contains(out.get("catalog")))}
    @Test fun draftCleanedSeparatelyWithoutTouchingCatalog() {val s=LegacyFixtures.state(root(),root());s.add("draft",LegacyFixtures.marked(item()));val out=migrate(s);assertEquals(s.get("catalog"),out.get("catalog"));assertEquals(item().get("sinopsis"),out.getAsJsonObject("draft").get("sinopsis"));assertEquals(path(item(),"1/1/sinopsis"),path(out.getAsJsonObject("draft"),"1/1/sinopsis"))}
    @Test fun restoreOldSnapshotIsFilteredAgainAfterRestart() {val store=LegacyFixtures.Store();val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());store.data=raw;val repo=AdminRepository(store);assertFalse(RetiredMetadata.contains(repo.catalog));assertTrue(store.archives.isNotEmpty());store.data=raw;assertFalse(RetiredMetadata.contains(AdminRepository(store).catalog))}
    @Test fun backupCreatedBeforeActiveStateMutation() {val store=LegacyFixtures.Store();val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());store.data=raw;val repo=AdminRepository(store);assertTrue(store.archives.values.any {it==raw});assertFalse(RetiredMetadata.contains(repo.catalog));assertTrue(repo.pending)}
    @Test fun archiveFailureDoesNotAlterOriginalState() {val store=LegacyFixtures.Store();val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());store.data=raw;store.failArchive=true;val repo=AdminRepository(store);assertEquals(raw,store.data);assertEquals(raw,repo.state);assertFalse(repo.writable);assertTrue(repo.recoveryNotice.contains("respaldo"))}
    @Test fun atomicStateWriteFailureKeepsOriginalAndPrivateBackup() {val store=LegacyFixtures.Store();val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());store.data=raw;store.failWrite=true;val repo=AdminRepository(store);assertEquals(raw,store.data);assertEquals(raw,repo.state);assertTrue(store.archives.values.any {it==raw})}
    @Test fun historicalBackupNotRewrittenByMigration() {val store=LegacyFixtures.Store();val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());raw.add("metadata_undo",JsonObject().apply {add("before",item());add("after",LegacyFixtures.marked(item()))});store.data=raw;val repo=AdminRepository(store);assertEquals(raw.get("metadata_undo"),repo.state.get("metadata_undo"));val saved=store.archives.values.map {it.deepCopy()};AdminRepository(store);assertTrue(saved.all {snapshot->store.archives.values.any {it==snapshot}})}
    @Test fun ledgerPreventsRelabelingOrCopyingQuarantinedValuesOnLaterSave() {val raw=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root());val store=LegacyFixtures.Store();store.data=raw;val repo=AdminRepository(store);val remote=LegacyFixtures.Remote(root());repo.refresh(remote);val edited=first(repo.catalog!!).deepCopy();edited.addProperty("custom_description",path(first(raw.getAsJsonObject("catalog")),"1/1/sinopsis")!!.asString);edited.addProperty("fuente","MANUAL");repo.saveItem(edited);assertFalse(first(repo.catalog!!).has("custom_description"))}
    @Test fun genuineNewTmdbRecoveryCanIndependentlySupplySameText() {val bad=LegacyFixtures.marked(item());val s=migrate(LegacyFixtures.state(root(bad),root()));val safe=first(s.getAsJsonObject("catalog")).deepCopy();LegacyFixtures.target(safe,"1/1/sinopsis").add("sinopsis",path(bad,"1/1/sinopsis")!!.deepCopy());safe.getAsJsonObject("fuentes_metadata").getAsJsonObject("recuperacion_selectiva").add("1/1/sinopsis",LegacyFixtures.obj("""{"fuente":"TMDB"}"""));val next=RetiredMetadata.verified(s,safe,setOf("1/1/sinopsis")).apply {add("draft",safe)};assertEquals(path(bad,"1/1/sinopsis"),path(migrate(next).getAsJsonObject("draft"),"1/1/sinopsis"))}
    @Test fun restrictedSynopsisCopiedToAnotherRecordIsNotLaundered() {val bad=LegacyFixtures.marked(item());val copied=LegacyFixtures.item("other").apply {add("sinopsis",path(bad,"1/1/sinopsis")!!.deepCopy())};val output=CatalogRules.publicCopy(LegacyFixtures.catalog(bad,copied));assertFalse(CatalogRules.items(output)[1].has("sinopsis"))}
    @Test fun copiesInUnknownArraysAreRemovedWithoutDeletingOtherEntries() {val bad=LegacyFixtures.marked(item());bad.add("future_notes",JsonArray().apply {add("Comentario propio");add(path(bad,"1/1/sinopsis")!!.deepCopy())});val out=first(CatalogRules.publicCopy(root(bad)));assertEquals(listOf("Comentario propio"),out.array("future_notes").map {it.asString})}
    @Test fun globalRestrictedBaseCannotRestoreEpisodeTextWithoutIndependentProvenance() {val base=item().apply {addProperty("fuente_episodios","TheTVDB")};val s=LegacyFixtures.state(root(LegacyFixtures.marked(item())),root(base));val out=first(migrate(s).getAsJsonObject("catalog"));assertNull(path(out,"1/1/sinopsis"))}
    @Test fun nestedRootRetiredBlobRemovedWithoutLosingUnknownSiblings() {val r=root().apply {add("legacy",LegacyFixtures.obj("""{"keep":7,"nested":{"publicacion_bloqueada":true,"text":"Histórico desconocido"}}"""))};val out=CatalogRules.publicCopy(r);assertEquals(7L,out.getAsJsonObject("legacy").number("keep"));assertFalse(out.getAsJsonObject("legacy").has("nested"));assertEquals(r.get("items"),out.get("items"))}
    @Test fun unrelatedUnknownRootStringAndTmdbTagPreserved() {val r=root().apply {addProperty("future_text","TheTVDB");addProperty("fuente","TMDB");addProperty("publicacion_bloqueada",true)};val out=CatalogRules.publicCopy(r);assertEquals("TheTVDB",out.text("future_text"));assertEquals("TMDB",out.text("fuente"));assertFalse(out.has("publicacion_bloqueada"))}
    @Test fun rejectedRemovedProviderCannotBeAppliedEvenWithLicenseFlag() {val c=RecoveryCandidate("TheTVDB",1,"Synthetic","2020","https://thetvdb.com/series/test","spa",JsonObject());val plan=MetadataRecovery.compare(item(),RecoveryData(c,LegacyFixtures.obj("""{"sinopsis":"Retirado"}""")));assertThrows(IllegalArgumentException::class.java){MetadataRecovery.apply(plan,plan.changes.map {it.path.key}.toSet(),emptySet(),true)}}
}
